import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {parseFx,ForexService} from '../.build/src/glance/forex.js';
import {DEFAULT_PREFERENCES,GLANCE_VERSION,validPreferences,validFx,validGlance,eligiblePublication} from '../.build/src/glance/contracts.js';
import {keyThing,localDay,quoteCurrency,forecastRange,currentLocalCards,nextGlanceDelay} from '../.build/src/glance/presentation.js';
import {readPreferences,savePreferences,clearPreferences} from '../.build/src/glance/preferences.js';
import {handleGlance} from '../.build/api/glance.js';
const now=Date.parse('2026-11-15T12:00:00Z');
const xml=(latest='2026-11-13',extra='')=>`<?xml version="1.0"?><gesmes:Envelope xmlns:gesmes="http://www.gesmes.org/xml/2002-08-01" xmlns="http://www.ecb.int/vocabulary/2002-08-01/eurofxref"><gesmes:subject>Reference rates</gesmes:subject><gesmes:Sender><gesmes:name>European Central Bank</gesmes:name></gesmes:Sender><Cube><Cube time="${latest}"><Cube currency="USD" rate="1.10"/><Cube currency="RON" rate="5.20"/>${extra}</Cube><Cube time="2026-11-12"><Cube currency="USD" rate="1.09"/><Cube currency="RON" rate="5.19"/></Cube></Cube></gesmes:Envelope>`;
const publication=(changes={})=>({id:'a'.repeat(24),identity:'nasa:fixture',title:'A source publication',topic:'science',kind:'publication',sourceUrl:'https://www.nasa.gov/news-release/example/',publisher:'NASA',sourceIds:['nasa-news'],date:'2026-11-13T11:00:00Z',dateLabel:'Published',observedAt:new Date(now).toISOString(),contentHash:'b'.repeat(64),boundary:'Publisher metadata, not an independently verified report.',deadline:null,version:null,attribution:'NASA',sourceState:'verified',...changes});
const city={id:'2512989',name:'Palma',countryCode:'ES',country:'Spain',region:'Balearic Islands',lat:39.57,lon:2.65,timezone:'Europe/Madrid'};
const forecast={id:'weather:fixture',kind:'forecast',title:'Weather for the next six full hours',text:'Hourly forecast temperatures 12–15.4 °C. Total precipitation 0 mm over the six hourly periods.',publisher:'MET Norway',sourceUrl:'https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=39.5700&lon=2.6500',sourceUpdatedAt:new Date(now-3600000).toISOString(),checkedAt:new Date(now).toISOString(),validFrom:new Date(now).toISOString(),validTo:new Date(now+6*3600000).toISOString(),facts:[],boundary:'City-centre forecast.'};
const local=(cards)=>({version:'dlkt-local-1',city,checkedAt:new Date(now).toISOString(),state:'ready',weatherState:'ready',transportState:'not-covered',cards});

test('ECB reference parser preserves dated values and preceding reference, without calling them live',()=>{const x=parseFx(xml(),now);assert.equal(x.date,'2026-11-13');assert.equal(x.previousDate,'2026-11-12');assert.equal(x.rates.USD,1.1);assert.equal(x.previousRates.USD,1.09);assert.ok(validFx(x,now));assert.equal(validFx(x,now+6*3600000+1),false);});
for(const [name,mutate] of [
 ['wrong issuer',s=>s.replace('European Central Bank','Other bank')],
 ['wrong XML namespace',s=>s.replace('2002-08-01','2026-08-01')],
 ['external entity',s=>'<!DOCTYPE data [<!ENTITY x SYSTEM "file:///etc/passwd">]>'+s],
 ['malformed XML',s=>s.slice(0,-10)],
 ['negative rate',s=>s.replace('rate="1.10"','rate="-1"')],
 ['infinite rate',s=>s.replace('rate="1.10"','rate="Infinity"')],
 ['duplicate currency',s=>s.replace('<Cube currency="USD" rate="1.10"/>','<Cube currency="USD" rate="1.10"/><Cube currency="USD" rate="1.11"/>')],
 ['duplicate date',s=>s.replace('2026-11-12','2026-11-13')],
 ['impossible date',s=>s.replace('2026-11-13','2026-11-31')],
 ['future reference',s=>s.replace('2026-11-13','2026-11-16')],
 ['expired latest reference',s=>s.replaceAll('2026-11','2026-10')],
 ['oversize response',s=>s+' '.repeat(1048576)]
])test(`ECB rejects ${name}`,()=>assert.throws(()=>parseFx(mutate(xml()),now)));

test('ECB service coalesces requests, honors bounded transport and expires its cache',async()=>{let calls=0,clock=now;let release;const wait=new Promise(r=>{release=r;});const service=new ForexService(async(url,init)=>{calls++;assert.equal(url,'https://www.ecb.europa.eu/stats/eurofxref/eurofxref-hist-90d.xml');assert.equal(init.redirect,'manual');assert.equal(init.credentials,'omit');await wait;return new Response(xml(),{headers:{'content-type':'text/xml'}});},()=>clock);const a=service.read(),b=service.read();release();assert.deepEqual(await a,await b);assert.equal(calls,1);await service.read();assert.equal(calls,1);clock+=3600001;await service.read();assert.equal(calls,2);clock=Date.parse('2026-12-16T00:00:00Z');assert.equal(await service.read(),null);assert.equal(calls,2);});
test('ECB redirects, incompatible MIME and oversized declared body fail closed with backoff',async()=>{for(const response of [new Response(null,{status:302,headers:{location:'https://example.com'}}),new Response(xml(),{headers:{'content-type':'text/html'}}),new Response(xml(),{headers:{'content-type':'text/xml','content-length':'1048577'}})]){let calls=0;const service=new ForexService(async()=>{calls++;return response;},()=>now);assert.equal(await service.read(),null);assert.equal(await service.read(),null);assert.equal(calls,1);}});
test('ECB failure removes an earlier quote rather than relabelling it current',async()=>{let n=0,clock=now;const service=new ForexService(async()=>{if(n++===0)return new Response(xml(),{headers:{'content-type':'text/xml'}});throw Error('offline');},()=>clock);assert.ok(await service.read());clock+=3600001;assert.equal(await service.read(),null);});
test('signal preferences accept explicit browser choices and reject invalid or extra fields',()=>{assert.ok(validPreferences(DEFAULT_PREFERENCES));assert.ok(validPreferences({...DEFAULT_PREFERENCES,weather:false,forex:false,keyThing:false,currency:'RON'}));for(const value of [{...DEFAULT_PREFERENCES,currency:'BTC'},{...DEFAULT_PREFERENCES,weather:'yes'},{...DEFAULT_PREFERENCES,extra:true},{...DEFAULT_PREFERENCES,version:'other'}])assert.equal(validPreferences(value),false);assert.equal(quoteCurrency('RO'),'RON');assert.equal(quoteCurrency('ES'),'USD');});
test('spotlight rejects source impersonation, stale records and wrong geographic scope',()=>{const p=publication();assert.ok(eligiblePublication(p,now));for(const bad of [{...p,publisher:'Other'},{...p,sourceState:'stale'},{...p,date:'2026-10-01T00:00:00Z'},{...p,observedAt:new Date(now-6*3600000-1).toISOString()}])assert.equal(eligiblePublication(bad,now),false);const uk=publication({topic:'public-affairs',sourceIds:['govuk-news'],publisher:'UK Government'});assert.equal(keyThing([uk],null,city,[],now,city.timezone),null);assert.equal(keyThing([p],null,city,['business'],now,city.timezone),null);assert.equal(keyThing([uk],null,city,['public-affairs'],now,city.timezone)?.publication,uk);});
test('key thing gives selected topics precedence and keeps the original publication date',()=>{const older=publication(),newer=publication({id:'c'.repeat(24),date:'2026-11-14T10:00:00Z',topic:'environment',publisher:'U.S. Geological Survey',sourceIds:['usgs-news']});assert.equal(keyThing([older,newer],null,null,['science'],now,'UTC')?.publication,older);assert.equal(keyThing([older,newer],null,null,[],now,'UTC')?.publication,newer);assert.equal(keyThing([],null,null,[],now,'UTC'),null);});
test('local event must still be upcoming today and expires with its source check',()=>{const event={...forecast,id:'event:fixture',kind:'event',title:'Scheduled local event',validTo:new Date(now+300000).toISOString(),context:{startsAt:new Date(now+3600000).toISOString(),section:'discover',status:'scheduled',place:'Palma',when:'Today',why:'Municipal listing',action:'Open listing',sourceDate:'2026-11-15',documentHash:'e'.repeat(64),documentUrl:'https://www.palmacultura.com/index.php?Idi=2'}};assert.equal(keyThing([publication()],local([event]),city,[],now,city.timezone)?.kind,'event');assert.equal(keyThing([publication()],local([event]),city,[],now+300001,city.timezone),null);assert.equal(keyThing([publication()],local([event]),city,['science'],now+300001,city.timezone)?.kind,'publication');const past={...event,context:{...event.context,startsAt:new Date(now-1).toISOString()}};assert.equal(keyThing([],local([past]),city,[],now,city.timezone),null);assert.equal(localDay(Date.parse('2026-11-15T23:30:00Z'),'Europe/Bucharest'),'2026-11-16');});
test('weather range is a forecast and expired source cards stop being current',()=>{assert.equal(forecastRange(forecast),'12–15.4 °C');assert.equal(forecastRange({...forecast,kind:'transport'}),null);assert.equal(currentLocalCards(local([forecast]),city,now).length,1);assert.equal(currentLocalCards(local([forecast]),city,now+6*3600000).length,0);assert.equal(currentLocalCards(local([forecast]),{...city,id:'123'},now).length,0);});
test('public glance schema rejects unpublished cards and expired FX even if shape is correct',()=>{const snapshot={version:GLANCE_VERSION,generatedAt:new Date(now).toISOString(),forex:parseFx(xml(),now),publications:[publication()]};assert.ok(validGlance(snapshot,now));assert.equal(validGlance({...snapshot,publications:[publication({sourceIds:['unknown']})]},now),false);assert.equal(validGlance(snapshot,now+6*3600000+1),false);});
function response(){return{headers:{},statusCode:0,body:'',setHeader(k,v){this.headers[k]=v;},end(v=''){this.body=v;}};}
test('glance API is public shared evidence with no preference or arbitrary source query',async()=>{let n=0;const load=async()=>{n++;return{version:GLANCE_VERSION,generatedAt:new Date(now).toISOString(),forex:null,publications:[]};};for(const req of [{method:'POST',url:'/api/glance',headers:{}},{method:'GET',url:'/api/glance?currency=RON',headers:{}},{method:'GET',url:'/api/glance?url=https://example.com',headers:{}}]){const res=response();await handleGlance(req,res,load);assert.ok([400,405].includes(res.statusCode));assert.equal(res.headers['Cache-Control'],'no-store');}assert.equal(n,0);const res=response();await handleGlance({method:'GET',url:'/api/glance',headers:{}},res,load);assert.equal(res.statusCode,200);assert.equal(res.headers['Cache-Control'],'public, max-age=0, s-maxage=300');const head=response();await handleGlance({method:'HEAD',url:'/api/glance',headers:{}},head,load);assert.equal(head.body,'');});
test('glance API does not expose internal failures',async()=>{const res=response();await handleGlance({method:'GET',url:'/api/glance',headers:{}},res,async()=>{throw Error('internal-secret');});assert.equal(res.statusCode,503);assert.equal(res.headers['Cache-Control'],'no-store');assert.doesNotMatch(res.body,/internal-secret/);});
test('brand CTA, bounded source requests and safe DOM survive asset compilation',()=>{const html=readFileSync('public/iceo.html','utf8'),js=readFileSync('public/glance-browser.js','utf8');assert.match(html,/Daily Life\. Key Things\./u);assert.match(html,/data-daily-build>Find my key things/u);assert.match(js,/fetch\('\/api\/glance'/u);assert.doesNotMatch(js,/innerHTML|outerHTML|insertAdjacentHTML|document\.cookie|eval\s*\(|navigator\.geolocation|setInterval/u);assert.match(js,/Applied for this visit\. Browser storage is unavailable\./u);assert.match(js,/savePreferences/u);for(const name of ['contracts','presentation','preferences','ticker','weather-motion','browser']){const compiled=readFileSync(`.build/src/glance/${name}.js`,'utf8').replace(/^\/\/# sourceMappingURL=.*\r?\n?/gmu,'').replaceAll("'./contracts.js'","'./glance-contracts.js'").replaceAll("'./presentation.js'","'./glance-presentation.js'").replaceAll("'./preferences.js'","'./glance-preferences.js'").replaceAll("'./ticker.js'","'./glance-ticker.js'").replaceAll("'./weather-motion.js'","'./glance-weather-motion.js'").replaceAll("'../local/contracts.js'","'./local-contracts.js'").replaceAll('../iceo/','./').replaceAll("'../i18n/browser.js'","'./i18n-browser.js'");assert.equal(readFileSync(`public/glance-${name}.js`,'utf8'),compiled);}});

test('open-tab reprojection targets the first expiry instead of waiting thirty seconds',()=>{assert.equal(nextGlanceDelay([],[],null,now),30000);assert.equal(nextGlanceDelay([{...forecast,validTo:new Date(now+500).toISOString()}],[],null,now),510);assert.equal(nextGlanceDelay([],[publication({observedAt:new Date(now-6*3600000+100).toISOString()})],null,now),110);assert.equal(nextGlanceDelay([],[],{...parseFx(xml(),now),checkedAt:new Date(now-6*3600000+200).toISOString()},now),210);});
test('denied storage, corrupt values and explicit saves preserve usable visit preferences',()=>{const denied=()=>{throw Error('SecurityError');};assert.deepEqual(readPreferences(denied),DEFAULT_PREFERENCES);const chosen={...DEFAULT_PREFERENCES,currency:'RON',weather:false};assert.equal(savePreferences(chosen,denied),false);assert.equal(chosen.currency,'RON');assert.doesNotThrow(()=>clearPreferences(denied));let writes=0,raw='broken';const store={getItem:()=>raw,setItem:(_k,v)=>{writes++;raw=v;},removeItem:()=>{raw='';}};assert.deepEqual(readPreferences(()=>store),DEFAULT_PREFERENCES);assert.equal(writes,0);assert.equal(savePreferences(chosen,()=>store),true);assert.equal(writes,1);assert.deepEqual(readPreferences(()=>store),chosen);clearPreferences(()=>store);assert.deepEqual(readPreferences(()=>store),DEFAULT_PREFERENCES);});
